def transform(grid):
    H, W = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # The solid separator rows and columns define panels. Find the panel
    # containing the non-background pattern and tile that pattern throughout.
    sep = next((v for v in set(sum(grid, []))
                if any(all(x == v for x in row) for row in grid)), None)
    if sep is None:
        return out

    divider_rows = [i for i, row in enumerate(grid) if all(x == sep for x in row)]
    divider_cols = [j for j in range(W) if all(grid[i][j] == sep for i in range(H))]
    row_starts = [0] + [i + 1 for i in divider_rows]
    row_ends = divider_rows + [H]
    col_starts = [0] + [j + 1 for j in divider_cols]
    col_ends = divider_cols + [W]

    colors = set(sum(grid, [])) - {sep}
    background = min(colors) if colors else sep
    source = None
    for r0, r1 in zip(row_starts, row_ends):
        for c0, c1 in zip(col_starts, col_ends):
            if any(grid[y][x] != background and grid[y][x] != sep
                   for y in range(r0, r1) for x in range(c0, c1)):
                source = (r0, r1, c0, c1)
                break
        if source:
            break
    if source is None:
        return out

    sr, er, sc, ec = source
    h, w = er - sr, ec - sc
    for r0, r1 in zip(row_starts, row_ends):
        for c0, c1 in zip(col_starts, col_ends):
            for y in range(r0, r1):
                for x in range(c0, c1):
                    value = grid[sr + (y - r0) % h][sc + (x - c0) % w]
                    if value != sep:
                        out[y][x] = value
    return out

